style.css:
@-moz-document domain("roblox.com") {
/* Container for the greeting */
  .stylish-greeting {
    display: flex;
    align-items: center;
    font-size: 24px;
    font-weight: bold;
    margin: 20px;
    color: white;
    background-color: #1c1c1c;
    padding: 12px 20px;
    border-radius: 10px;
    width: fit-content;
  }

  /* Avatar image styling */
  .stylish-greeting img {
    width: 64px;
    height: 64px;
    border-radius: 50%;
    margin-right: 15px;
    border: 2px solid #e33c3c;
  }

  /* Inject into the page header */
  body::before {
    content: "";
    display: block;
  }

  /* Add the greeting dynamically */
  body::after {
    content: "Morning, Venhel";
    display: flex;
    align-items: center;
    position: fixed;
    top: 80px;
    left: 20px;
    font-size: 24px;
    font-weight: bold;
    background-color: #1c1c1c;
    color: white;
    padding: 12px 20px 12px 90px;
    border-radius: 10px;
    background-image: url('https://thumbnails.roblox.com/v1/users/avatar-headshot?userIds=92321971&size=100x100&format=Png&isCircular=true');
    background-repeat: no-repeat;
    background-size: 64px 64px;
    background-position: 12px center;
    z-index: 1000;
  }
}
